//! Oracle driver and shared builders of the media-needs join (L09-J).
//!
//! `fixtures/object-media-link-needs/oracle.txt` is generated by `tools/gen.js`
//! from the SHIPPED export loop (`exportRenderPNGsToDir`, `pad4`,
//! `exportDataURLToBytes` of `src/js/export.js`) driving the SHIPPED video frame
//! selection of `src/js/native-video-bridge.js`, both cut verbatim at fbe4b8a3.
//! Row grammar (space separated, f64 = 16 hex digits of the bit pattern):
//!
//! `E fc off tr imode fb rv start end entries`
//!
//! - `fc` frameCount; `off` the placement offset (decimal i64); `tr` the layer
//!   has timeRemap (0|1); `imode` `u` or `s:<text>`; `fb` legacy frameBlend;
//!   `rv` the time-remap value or `-` (the sampler answers null);
//! - `start end` the exported timeline range;
//! - `entries` are `<ordinal>=<frame>=<sel>` joined by `;`, where `sel` is
//!   `S<n>` (one decodable source frame), `B<from>/<to>/<weight hex>` (a blend
//!   pair) or `X` (the shipped selection is not a decodable index, so the native
//!   need must be the typed `InvalidSourceFrame` refusal).
//!
//! The native side builds the same layer from one embedded video asset, one
//! placement carrying the offset and the facts above, and compares the need of
//! every exported frame to the shipped loop's selection.
use super::{needs_for_frame, MediaNeed, NeedsRefusal};
use crate::object_document::media_timing::object_media_link_join::LocatorNamespace;
use crate::object_document::media_timing::object_media_link_plan::{
    AudioFacts, MediaFacts, PlanInput, VideoFacts,
};
use crate::object_document::media_timing::object_media_link_state::ResolveTable;
use crate::object_document::media_timing::object_media_timing_audio::{PlaybackEnv, VolumeSampler};
use crate::object_document::media_timing::object_media_timing_video::TimeRemapPort;
use crate::object_document::{
    AssetId, AssetInventory, AssetKind, AssetPlacement, AssetRecord, AssetSource, AssetTarget,
};
use std::collections::HashMap;
use std::sync::Arc;

const ORACLE: &str = include_str!("fixtures/object-media-link-needs/oracle.txt");

pub(crate) fn hex(bits: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(bits, 16).expect("hex bits"))
}

// ---- shared builders ------------------------------------------------------

pub(crate) fn aid(id: &str) -> AssetId {
    AssetId::new(id.to_string()).expect("valid asset id")
}

pub(crate) fn embedded(kind: AssetKind, id: &str) -> Arc<AssetRecord> {
    let media_type = match kind {
        AssetKind::Image => "image/png",
        AssetKind::Video => "video/mp4",
        AssetKind::Audio => "audio/mpeg",
        AssetKind::Font => "font/ttf",
    };
    let source =
        AssetSource::admitted_embedded(media_type.to_string(), Arc::new(vec![1, 2, 3]), 1 << 16)
            .expect("embedded source");
    Arc::new(AssetRecord::new(aid(id), format!("{id}.bin"), kind, source).expect("record"))
}

pub(crate) fn linked(kind: AssetKind, id: &str, locator: &str) -> Arc<AssetRecord> {
    let source = AssetSource::linked(locator.to_string(), 4096).expect("linked source");
    Arc::new(AssetRecord::new(aid(id), format!("{id}.bin"), kind, source).expect("record"))
}

pub(crate) fn drawing(layer: &str) -> AssetTarget {
    AssetTarget::Drawing {
        context_id: "ctx".to_string(),
        layer_uid: layer.to_string(),
        stroke_id: None,
    }
}

pub(crate) fn track(uid: &str) -> AssetTarget {
    AssetTarget::AudioTrack {
        track_uid: uid.to_string(),
    }
}

pub(crate) fn font(layer: &str) -> AssetTarget {
    AssetTarget::Text {
        context_id: "ctx".to_string(),
        layer_uid: layer.to_string(),
        stroke_id: None,
    }
}

pub(crate) fn place(id: &str, asset: &str, target: AssetTarget, offset: i64) -> AssetPlacement {
    AssetPlacement::new(id.to_string(), aid(asset), target, offset).expect("placement")
}

pub(crate) fn inventory(
    records: Vec<Arc<AssetRecord>>,
    placements: Vec<AssetPlacement>,
) -> AssetInventory {
    AssetInventory::new(records, placements, 64, 64).expect("inventory")
}

/// A time-remap sampler with a fixed answer (`None` is JS `null`).
pub(crate) struct Remap(pub Option<f64>);

impl TimeRemapPort for Remap {
    fn remap_value(&self, _frame: f64) -> Option<f64> {
        self.0
    }
}

/// A sampler that follows the timeline frame except at one frame, where it
/// answers `NaN` (the kernel refuses a non-finite remap value).
pub(crate) struct NanAt(pub f64);

impl TimeRemapPort for NanAt {
    fn remap_value(&self, frame: f64) -> Option<f64> {
        Some(if frame == self.0 { f64::NAN } else { frame })
    }
}

/// Facts keyed by placement id; a placement without an entry gets `None`.
#[derive(Default)]
pub(crate) struct Facts {
    pub video: HashMap<String, VideoFacts>,
    pub remap: HashMap<String, Box<dyn TimeRemapPort>>,
    pub audio: HashMap<String, AudioFacts>,
}

impl MediaFacts for Facts {
    fn video(&self, placement_id: &str) -> Option<VideoFacts> {
        self.video.get(placement_id).cloned()
    }
    fn time_remap(&self, placement_id: &str) -> Option<&dyn TimeRemapPort> {
        self.remap.get(placement_id).map(|port| port.as_ref())
    }
    fn audio(&self, placement_id: &str) -> Option<AudioFacts> {
        self.audio.get(placement_id).copied()
    }
    fn volume_sampler(&self, _placement_id: &str) -> Option<&dyn VolumeSampler> {
        None
    }
}

pub(crate) fn video_facts(frame_count: f64, time_remap: bool) -> VideoFacts {
    VideoFacts {
        frame_count,
        time_remap,
        interp_mode: None,
        frame_blend: false,
    }
}

pub(crate) fn input<'a>(
    inventory: &'a AssetInventory,
    links: &'a ResolveTable,
    facts: &'a Facts,
) -> PlanInput<'a> {
    PlanInput {
        inventory,
        links,
        namespace: LocatorNamespace::DesktopPath,
        now_ms: 0,
        env: PlaybackEnv {
            fps: 24.0,
            context_isolated: false,
            audio_context: true,
        },
        facts,
    }
}

// ---- oracle driver ----------------------------------------------------------

/// The function under test: the real join, or a mutant spliced around it.
pub(crate) type Candidate<'a> =
    dyn Fn(&PlanInput<'_>, u32) -> Result<Vec<MediaNeed>, NeedsRefusal> + 'a;

/// What `run_oracle` saw: rows, compared entries and per-class entry counts.
#[derive(Debug, Default, PartialEq, Eq)]
pub(crate) struct Run {
    pub rows: usize,
    pub entries: usize,
    pub single: usize,
    pub blend: usize,
    pub refused: usize,
    pub mismatches: usize,
}

fn expected_need(sel: &str) -> Result<MediaNeed, ()> {
    let placement_id = "pv".to_string();
    let asset_id = aid("vid");
    if sel == "X" {
        return Err(());
    }
    if let Some(n) = sel.strip_prefix('S') {
        return Ok(MediaNeed::Single {
            placement_id,
            asset_id,
            frame: n.parse().expect("decodable frame"),
        });
    }
    let pair = sel.strip_prefix('B').expect("S, B or X");
    let parts: Vec<&str> = pair.split('/').collect();
    Ok(MediaNeed::Blend {
        placement_id,
        asset_id,
        from: parts[0].parse().expect("from"),
        to: parts[1].parse().expect("to"),
        weight: hex(parts[2]),
    })
}

fn row_facts(tokens: &[&str]) -> (i64, Facts) {
    let offset: i64 = tokens[2].parse().expect("offset");
    let mut facts = Facts::default();
    facts.video.insert(
        "pv".to_string(),
        VideoFacts {
            frame_count: hex(tokens[1]),
            time_remap: tokens[3] == "1",
            interp_mode: tokens[4].strip_prefix("s:").map(str::to_string),
            frame_blend: tokens[5] == "1",
        },
    );
    let remap = if tokens[6] == "-" {
        None
    } else {
        Some(hex(tokens[6]))
    };
    facts.remap.insert("pv".to_string(), Box::new(Remap(remap)));
    (offset, facts)
}

/// Replays every oracle row through `candidate`. A row is `tokens[0] == "E"`;
/// `tokens[1..=6]` are the layer, `tokens[7..=8]` the range, `tokens[9]` the entries.
pub(crate) fn run_oracle(candidate: &Candidate<'_>) -> Run {
    let mut run = Run::default();
    let table = ResolveTable::new();
    for line in ORACLE.lines().filter(|line| !line.starts_with('#')) {
        let tokens: Vec<&str> = line.split_whitespace().collect();
        assert_eq!(tokens.len(), 10, "row shape: {line}");
        assert_eq!(tokens[0], "E");
        let (offset, facts) = row_facts(&tokens[..7]);
        let inv = inventory(
            vec![embedded(AssetKind::Video, "vid")],
            vec![place("pv", "vid", drawing("lv"), offset)],
        );
        let plan_input = input(&inv, &table, &facts);
        let start: u32 = tokens[7].parse().expect("start");
        run.rows += 1;
        for entry in tokens[9].split(';') {
            let fields: Vec<&str> = entry.split('=').collect();
            let (ordinal, frame): (u32, u32) = (
                fields[0].parse().expect("ordinal"),
                fields[1].parse().expect("frame"),
            );
            // The shipped loop writes frame_000<ordinal> for timeline frame start + ordinal - 1.
            assert_eq!(ordinal, frame - start + 1, "ordinal pairing: {line}");
            let got = candidate(&plan_input, frame);
            let ok = match expected_need(fields[2]) {
                Ok(need) => {
                    if matches!(need, MediaNeed::Single { .. }) {
                        run.single += 1;
                    } else {
                        run.blend += 1;
                    }
                    got == Ok(vec![need])
                }
                Err(()) => {
                    run.refused += 1;
                    matches!(&got, Err(NeedsRefusal::InvalidSourceFrame { placement_id, .. })
                        if placement_id == "pv")
                }
            };
            run.entries += 1;
            if !ok {
                run.mismatches += 1;
            }
        }
    }
    run
}

#[test]
fn generated_oracle_matches_the_shipped_export_loop() {
    let run = run_oracle(&|input, frame| needs_for_frame(input, frame));
    assert_eq!(run.mismatches, 0);
    assert_eq!(run.rows, 648);
}

#[test]
fn oracle_has_the_documented_class_counts() {
    // The generator header and the replay agree: 1650 single, 462 blend, 264 refused.
    assert!(ORACLE.contains("# rows 648 entries S 1650 B 462 X 264"));
    let run = run_oracle(&|input, frame| needs_for_frame(input, frame));
    assert_eq!(
        (run.entries, run.single, run.blend, run.refused),
        (2376, 1650, 462, 264)
    );
}

#[test]
fn oracle_pins_extreme_offsets_and_the_fractional_frame_count() {
    // Literal rows from the generated file: the +-(2^53 - 1) offsets clamp to the first
    // frame (frame - MAX < 0) or the last (frame + MAX > last), and frameCount 2.5 turns
    // the remapped blend partner fractional.
    assert!(ORACLE
        .contains("E 4024000000000000 9007199254740991 0 u 0 - 0 3 1=0=S0;2=1=S0;3=2=S0;4=3=S0"));
    assert!(ORACLE
        .contains("E 4024000000000000 -9007199254740991 0 u 0 - 0 3 1=0=S9;2=1=S9;3=2=S9;4=3=S9"));
    assert!(ORACLE
        .contains("E 4004000000000000 0 1 s:blend 0 400c000000000000 0 3 1=0=X;2=1=X;3=2=X;4=3=X"));
}
